const SECTIONS: [&[GridNote]; 12] = [
    INTRO, VERSE1, CHORUS1, VERSE2, CHORUS2, SOLO1, VERSE3, CHORUS3, BRIDGE1, SOLO2, BRIDGE2,
    FINALE,
];

pub fn lead_guitar_score(bpm: f32) -> Vec<ScheduledNote<ElectricGuitarArticulation>> {
    collect_score_from_sections(&SECTIONS, bpm)
}
